-- Generated by `prisma migrate dev --create-only` as three NOT NULL columns and
-- three unique indexes; the columns are added nullable, backfilled and then
-- made NOT NULL by hand, because the tables may already hold rows.

-- AlterTable
ALTER TABLE "travtrack_share_past_flights" ADD COLUMN     "dedupe_key" TEXT;

-- AlterTable
ALTER TABLE "travtrack_share_past_homes" ADD COLUMN     "dedupe_key" TEXT;

-- AlterTable
ALTER TABLE "travtrack_share_past_spans" ADD COLUMN     "dedupe_key" TEXT;

-- ---------------------------------------------------------------------------
-- Hand-written from here (TravTrack plan T7, Codex review of the share
-- restrictions, third round). A recipient's read replays every restriction
-- recorded since the share, and the flight trigger fired on provider readings
-- (actual, runway, check-in times) that place no recorder window, so a busy
-- flight grew the replay without bound. Now each table holds one row per
-- distinct restriction: the key is an md5 of exactly the values that decide
-- it, a repeat is `ON CONFLICT DO NOTHING`, and the flight trigger fires only
-- when a value that places the window changed. `check:drift` cannot see the
-- triggers; `routes/__tests__/travtrack.shareRestrictionsRecorded.test.ts`
-- drives them.
-- ---------------------------------------------------------------------------

-- Existing rows get the key their values make; equal ones collapse into one
-- (they restrict the same thing, so nothing is lost).
UPDATE "travtrack_share_past_spans" SET "dedupe_key" = md5(ROW(
  "start_date", "end_date", "start_day", "end_day", "start_zone", "end_zone", "profile_zone"
)::text);
UPDATE "travtrack_share_past_flights" SET "dedupe_key" = md5(ROW(
  "departure_time", "arrival_time", "dep_time_semantics", "arr_time_semantics", "dep_timezone",
  "arr_timezone", "dep_precision", "arr_precision", "dep_iata", "dep_icao", "arr_iata", "arr_icao"
)::text);
UPDATE "travtrack_share_past_homes" SET "dedupe_key" = md5("home_place"::text);

DELETE FROM "travtrack_share_past_spans" a USING "travtrack_share_past_spans" b
WHERE a."snapshot_id" = b."snapshot_id" AND a."dedupe_key" = b."dedupe_key" AND a."id" > b."id";
DELETE FROM "travtrack_share_past_flights" a USING "travtrack_share_past_flights" b
WHERE a."snapshot_id" = b."snapshot_id" AND a."dedupe_key" = b."dedupe_key" AND a."id" > b."id";
DELETE FROM "travtrack_share_past_homes" a USING "travtrack_share_past_homes" b
WHERE a."snapshot_id" = b."snapshot_id" AND a."dedupe_key" = b."dedupe_key" AND a."id" > b."id";

ALTER TABLE "travtrack_share_past_spans" ALTER COLUMN "dedupe_key" SET NOT NULL;
ALTER TABLE "travtrack_share_past_flights" ALTER COLUMN "dedupe_key" SET NOT NULL;
ALTER TABLE "travtrack_share_past_homes" ALTER COLUMN "dedupe_key" SET NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "travtrack_share_past_flights_snapshot_id_dedupe_key_key" ON "travtrack_share_past_flights"("snapshot_id", "dedupe_key");

-- CreateIndex
CREATE UNIQUE INDEX "travtrack_share_past_homes_snapshot_id_dedupe_key_key" ON "travtrack_share_past_homes"("snapshot_id", "dedupe_key");

-- CreateIndex
CREATE UNIQUE INDEX "travtrack_share_past_spans_snapshot_id_dedupe_key_key" ON "travtrack_share_past_spans"("snapshot_id", "dedupe_key");

CREATE OR REPLACE FUNCTION travtrack_share_capture_trip_span()
RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  zone TEXT := (SELECT us."data" #>> '{display,timezone}' FROM "user_settings" us
                WHERE us."user_id" = OLD."user_id");
BEGIN
  INSERT INTO "travtrack_share_past_spans"
    ("id", "snapshot_id", "start_date", "end_date", "start_day", "end_day", "start_zone",
     "end_zone", "profile_zone", "dedupe_key")
  SELECT gen_random_uuid()::text, s."id", OLD."start_date", OLD."end_date", OLD."start_day",
         OLD."end_day", OLD."start_zone", OLD."end_zone", zone,
         md5(ROW(OLD."start_date", OLD."end_date", OLD."start_day", OLD."end_day",
                 OLD."start_zone", OLD."end_zone", zone)::text)
  FROM "travtrack_share_snapshots" s
  WHERE s."trip_id" = OLD."id" AND s."user_id" = OLD."user_id"
  ON CONFLICT ("snapshot_id", "dedupe_key") DO NOTHING;
  RETURN NULL;
END $fn$;

CREATE OR REPLACE FUNCTION travtrack_share_capture_profile_zone()
RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  owner_id TEXT;
  left_zone TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- No row before: the default (UTC) was in force.
    owner_id := NEW."user_id";
    left_zone := NULL;
  ELSE
    owner_id := OLD."user_id";
    left_zone := OLD."data" #>> '{display,timezone}';
    IF TG_OP = 'UPDATE'
       AND NEW."user_id" IS NOT DISTINCT FROM OLD."user_id"
       AND (NEW."data" #>> '{display,timezone}') IS NOT DISTINCT FROM left_zone THEN
      RETURN NULL;
    END IF;
  END IF;
  INSERT INTO "travtrack_share_past_spans"
    ("id", "snapshot_id", "start_date", "end_date", "start_day", "end_day", "start_zone",
     "end_zone", "profile_zone", "dedupe_key")
  SELECT gen_random_uuid()::text, s."id", t."start_date", t."end_date", t."start_day",
         t."end_day", t."start_zone", t."end_zone", left_zone,
         md5(ROW(t."start_date", t."end_date", t."start_day", t."end_day", t."start_zone",
                 t."end_zone", left_zone)::text)
  FROM "travtrack_share_snapshots" s
  JOIN "trips" t ON t."id" = s."trip_id"
  WHERE s."user_id" = owner_id AND (t."start_zone" IS NULL OR t."end_zone" IS NULL)
  ON CONFLICT ("snapshot_id", "dedupe_key") DO NOTHING;
  RETURN NULL;
END $fn$;

-- A flight that armed a recorder window on the trip (linked, not cancelled),
-- deleted or changed in anything that places that window: the trip, the
-- owner, the status, and the scheduled ends with their semantics, zones,
-- precisions and airports (`flightRecorderWindow` reads nothing else). The
-- provider readings are recorded as NULL: they place no window.
CREATE OR REPLACE FUNCTION travtrack_share_capture_flight()
RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW."trip_id" IS NOT DISTINCT FROM OLD."trip_id"
     AND NEW."user_id" IS NOT DISTINCT FROM OLD."user_id"
     AND NEW."status" IS NOT DISTINCT FROM OLD."status"
     AND NEW."departure_time" IS NOT DISTINCT FROM OLD."departure_time"
     AND NEW."arrival_time" IS NOT DISTINCT FROM OLD."arrival_time"
     AND NEW."dep_time_semantics" IS NOT DISTINCT FROM OLD."dep_time_semantics"
     AND NEW."arr_time_semantics" IS NOT DISTINCT FROM OLD."arr_time_semantics"
     AND NEW."dep_timezone" IS NOT DISTINCT FROM OLD."dep_timezone"
     AND NEW."arr_timezone" IS NOT DISTINCT FROM OLD."arr_timezone"
     AND NEW."dep_precision" IS NOT DISTINCT FROM OLD."dep_precision"
     AND NEW."arr_precision" IS NOT DISTINCT FROM OLD."arr_precision"
     AND NEW."dep_iata" IS NOT DISTINCT FROM OLD."dep_iata"
     AND NEW."dep_icao" IS NOT DISTINCT FROM OLD."dep_icao"
     AND NEW."arr_iata" IS NOT DISTINCT FROM OLD."arr_iata"
     AND NEW."arr_icao" IS NOT DISTINCT FROM OLD."arr_icao"
  THEN
    RETURN NULL;
  END IF;
  INSERT INTO "travtrack_share_past_flights"
    ("id", "snapshot_id", "departure_time", "arrival_time", "dep_time_semantics",
     "arr_time_semantics", "dep_timezone", "arr_timezone", "dep_precision", "arr_precision",
     "dep_iata", "dep_icao", "arr_iata", "arr_icao", "dedupe_key")
  SELECT gen_random_uuid()::text, s."id", OLD."departure_time", OLD."arrival_time",
         OLD."dep_time_semantics", OLD."arr_time_semantics", OLD."dep_timezone",
         OLD."arr_timezone", OLD."dep_precision", OLD."arr_precision", OLD."dep_iata",
         OLD."dep_icao", OLD."arr_iata", OLD."arr_icao",
         md5(ROW(OLD."departure_time", OLD."arrival_time", OLD."dep_time_semantics",
                 OLD."arr_time_semantics", OLD."dep_timezone", OLD."arr_timezone",
                 OLD."dep_precision", OLD."arr_precision", OLD."dep_iata", OLD."dep_icao",
                 OLD."arr_iata", OLD."arr_icao")::text)
  FROM "travtrack_share_snapshots" s
  WHERE s."trip_id" = OLD."trip_id" AND s."user_id" = OLD."user_id"
  ON CONFLICT ("snapshot_id", "dedupe_key") DO NOTHING;
  RETURN NULL;
END $fn$;

CREATE OR REPLACE FUNCTION travtrack_share_capture_home()
RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW."home_place" IS NOT DISTINCT FROM OLD."home_place" THEN
    RETURN NULL;
  END IF;
  INSERT INTO "travtrack_share_past_homes" ("id", "snapshot_id", "home_place", "dedupe_key")
  SELECT gen_random_uuid()::text, s."id", OLD."home_place", md5(OLD."home_place"::text)
  FROM "travtrack_share_snapshots" s
  WHERE s."user_id" = OLD."user_id"
  ON CONFLICT ("snapshot_id", "dedupe_key") DO NOTHING;
  RETURN NULL;
END $fn$;
